import re
import sys
from datetime import date

SWISS = re.compile(r"([0-9]{1,2})\.([0-9]{1,2})\.([0-9]{4})")
ISO = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def plausible(y, m, d):
    try:
        return date(y, m, d) != date(y, m, d + 1)
    except ValueError:
        return False


def convert(text):
    m = SWISS.fullmatch(text)
    if m:
        d, mo, y = map(int, m.groups())
        return date(y, mo, d).isoformat() if plausible(y, mo, d) else "invalid"
    m = ISO.fullmatch(text)
    if m:
        y, mo, d = map(int, m.groups())
        return date(y, mo, d).strftime("%d.%m.%Y") if plausible(y, mo, d) else "invalid"
    return "invalid"


def main():
    for line in sys.stdin:
        text = line.strip()
        if text:
            print(convert(text))
